/*
 * A115958  Numbers k having exactly 4 distinct prime factors, the largest of
 *          which is greater than or equal to sqrt(k) (i.e., sqrt(k)-rough
 *          numbers with exactly 4 distinct prime factors).
 * https://oeis.org/A115958
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   the sequence is generated by a sieve search. a(n) = the n-th
 *            integer k > 0 having exactly 4 distinct prime factors, the
 *            largest of which is at least ceil(sqrt(k))
 * Range:     u8 none, u16 n <= 56, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   floor_sqrt
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>
#include "../utils/floor_sqrt.h"

/* Enough for 10 000 terms. */
#define SIEVE_LIMIT 2000000ULL
#define MAX_TERMS   20000

/* Smallest prime factor array – 32‑bit is enough for the limit. */
static uint32_t spf[SIEVE_LIMIT + 1];
static uint64_t spf_limit = 0;

/* Sequence cache */
static seq_t seq[MAX_TERMS];
static size_t seq_len = 0;
static uint64_t next_candidate = 2;

/* Build the spf sieve once. */
static void build_spf(void)
{
    if (spf_limit != 0)
        return;
    for (size_t i = 0; i <= SIEVE_LIMIT; ++i)
        spf[i] = 0;
    for (size_t i = 2; i <= SIEVE_LIMIT; ++i) {
        if (spf[i] == 0) {
            spf[i] = (uint32_t)i;
            if (i <= SIEVE_LIMIT / i)
                for (uint64_t j = (uint64_t)i * (uint64_t)i; j <= SIEVE_LIMIT; j += i)
                    if (spf[(size_t)j] == 0)
                        spf[(size_t)j] = (uint32_t)i;
        }
    }
    spf[1] = 1;
    spf_limit = SIEVE_LIMIT;
}

/* Generate sequence values up to index n (1‑based). */
static void generate_until(idx_t n)
{
    if (n == 0 || seq_len >= (size_t)n)
        return;
    build_spf();

    while (seq_len < (size_t)n && next_candidate <= SIEVE_LIMIT) {
        uint64_t k = next_candidate++;
        uint64_t temp = k;
        int distinct = 0;
        uint64_t largest = 0;
        while (temp > 1) {
            uint64_t p = spf[(size_t)temp];
            if (p > largest)
                largest = p;
            ++distinct;
            while (temp % p == 0)
                temp /= p;
        }
        if (distinct == 4) {
            seq_t floor = floor_sqrt((seq_t)k);
            seq_t ceil = ((floor * floor == (seq_t)k) ? floor : floor + 1);
            if (largest >= (uint64_t)ceil) {
                if (seq_len < (size_t)MAX_TERMS)
                    seq[seq_len++] = (seq_t)k;
            }
        }
    }
}

/* Public sequence function. */
seq_t a(idx_t n)
{
    if (n == 0)
        return 0;
    generate_until(n);
    return seq[n - 1];
}
